<template>
  <div class="space-y-5">
    <header class="flex flex-wrap items-start justify-between gap-3"><div><h1 class="text-xl font-semibold">数据源任务</h1><p class="text-sm text-white/50 mt-1">使用自己的连接账号检查数据源与采集结构，任务关闭页面后仍会继续。</p></div><RouterLink to="/connections" class="ghost-button text-sm min-h-11 inline-flex items-center">返回数据源</RouterLink></header>
    <div role="tablist" aria-label="数据源任务分类" class="flex flex-wrap gap-2"><button v-for="item in tabs" :key="item.key" role="tab" class="ghost-button min-h-11" :aria-selected="tab===item.key" @click="selectTab(item.key)">{{item.label}}</button></div>
    <p v-if="error" role="alert" class="text-sm text-rose-300">{{error}}</p><p v-if="notice" role="status" class="text-sm text-emerald-200">{{notice}}</p>
    <form v-if="tab!=='history'" class="glass-card p-4 space-y-4" @submit.prevent="tab==='tasks'?createTask():saveSchedule()">
      <h2 class="font-medium">{{tab==='tasks'?'新建后台任务':editingVersion?'编辑定时计划':'新建定时计划'}}</h2>
      <div class="grid sm:grid-cols-2 lg:grid-cols-4 gap-3">
        <label class="text-xs text-white/60 space-y-2"><span>个人数据源</span><el-select v-model="connectionID" aria-label="任务数据源" class="!w-full" filterable :disabled="busy" @change="resetPlan"><el-option v-for="conn in connections" :key="conn.id" :value="conn.id" :label="conn.name" /></el-select></label>
        <label class="text-xs text-white/60 space-y-2"><span>任务类型</span><select v-model="kind" aria-label="任务类型" class="glass-input w-full text-sm" :disabled="busy" @change="resetPlan"><option value="check">连接检查</option><option value="collect" :disabled="!canCollect">采集结构</option></select></label>
        <label v-if="tab==='schedules'" class="text-xs text-white/60 space-y-2"><span>间隔（分钟）</span><input v-model.number="intervalMinutes" aria-label="计划间隔分钟" class="glass-input w-full text-sm" type="number" :min="kind==='collect'?60:5" max="10080" required :disabled="busy" /></label>
        <div class="flex items-end gap-2"><button class="liquid-button text-sm min-h-11" :disabled="busy||!connectionID||kind==='collect'&&!canCollect">{{busy?'提交中…':tab==='tasks'?'加入队列':'保存并启用'}}</button><button v-if="editingVersion" type="button" class="ghost-button text-xs min-h-11" :disabled="busy" @click="resetPlan">取消编辑</button></div>
      </div>
      <p class="text-xs text-white/45">{{tab==='tasks'?'重复点击复用同一请求编号；失败或中断后可手动重试。':'检查最短 5 分钟，采集最短 60 分钟。按保存后的间隔开始，不补跑停机期间的时段。'}}<span v-if="kind==='collect'&&!canCollect"> 当前身份或连接不支持采集。</span></p>
    </form>
    <div class="flex flex-wrap items-center gap-3"><template v-if="tab==='tasks'"><label class="text-xs text-white/60">任务状态 <select v-model="statusFilter" aria-label="任务状态筛选" class="glass-input text-sm ml-2" @change="page=1;load()"><option value="">全部</option><option v-for="(label,key) in taskStatusLabels" :key="key" :value="key">{{label}}</option></select></label></template><button class="ghost-button text-sm min-h-11" :disabled="loading||busy" @click="load">刷新列表</button><span class="text-xs text-white/40">仅显示当前工作空间自己的记录</span></div>
    <div v-loading="loading" class="space-y-3 min-h-24">
      <template v-if="tab==='tasks'"><article v-for="task in tasks" :key="task.id" class="glass-card p-4 space-y-3" :aria-label="task.connection_name+' '+(task.kind==='check'?'连接检查':'结构采集')"><div class="flex flex-wrap justify-between items-center gap-2"><h2 class="font-medium break-words">{{task.connection_name}} · {{task.kind==='check'?'连接检查':'结构采集'}}</h2><span class="text-xs" :class="task.status==='succeeded'?'text-emerald-200':['failed','unknown','interrupted'].includes(task.status)?'text-amber-200':'text-white/60'">{{taskStatusLabels[task.status]}}</span></div><p class="text-sm text-white/65">{{task.phase}}</p><progress v-if="activeTask(task.status)" class="w-full h-1.5 accent-indigo-400" :value="task.progress" max="100" :aria-label="'任务进度 '+task.progress+'%'" /><p v-if="task.status==='succeeded'&&task.kind==='collect'" class="text-xs text-white/50">已采集 {{task.result.tables??0}} 张表、{{task.result.views??0}} 个视图</p><p v-if="task.parent_id" class="text-xs text-white/40">手动重试任务，原记录保留</p><div class="flex flex-wrap items-center justify-between gap-3"><time class="text-xs text-white/40">{{formatTime(task.created_at)}}</time><div class="flex gap-2"><button v-if="activeTask(task.status)&&task.status!=='cancel_requested'" class="ghost-button text-xs min-h-11" :disabled="busy" @click="cancelTask(task)">取消任务</button><button v-if="retryableTask(task.status)&&task.connection_id" class="ghost-button text-xs min-h-11" :disabled="busy" @click="retryTask(task)">重新执行</button><RouterLink v-if="task.status==='succeeded'&&task.kind==='collect'" class="ghost-button text-xs min-h-11 inline-flex items-center" :to="`/assets?connection_id=${task.connection_id}`">查看数据目录</RouterLink></div></div></article></template>
      <template v-else-if="tab==='schedules'"><article v-for="schedule in schedules" :key="schedule.id" class="glass-card p-4 space-y-3"><div class="flex flex-wrap justify-between gap-2"><h2 class="font-medium">{{sourceName(schedule.connection_id)}} · {{schedule.kind==='check'?'连接检查':'结构采集'}}</h2><span class="text-xs" :class="schedule.enabled?'text-emerald-200':'text-white/45'">{{schedule.enabled?'已启用':'已暂停'}}</span></div><p class="text-sm text-white/60">每 {{schedule.interval_minutes}} 分钟<span v-if="schedule.enabled"> · 下次 {{formatTime(schedule.next_run_at)}}</span></p><p v-if="schedule.last_status" class="text-xs text-white/50">{{schedule.last_status}}</p><div class="flex flex-wrap gap-2"><button class="ghost-button text-xs min-h-11" :disabled="busy||!schedule.connection_id" @click="editSchedule(schedule)">编辑计划</button><button v-if="schedule.enabled" class="ghost-button text-xs min-h-11" :disabled="busy||!schedule.connection_id" @click="pauseSchedule(schedule)">暂停计划</button></div></article><p class="text-xs text-white/40">配置或成员权限变化后，旧计划会暂停；重新保存后绑定当前配置。</p></template>
      <template v-else><article v-for="check in history" :key="check.id" class="glass-card p-4 space-y-2"><div class="flex flex-wrap justify-between gap-2"><h2 class="font-medium">{{check.connection_name||'已删除的个人连接'}}</h2><span class="text-xs" :class="check.result.ok?'text-emerald-200':'text-amber-200'">{{check.result.ok?'检查通过':'检查失败'}}<span v-if="!check.current_config"> · 旧配置</span></span></div><p class="text-sm text-white/60">{{check.result.error||check.result.version||'连接可用'}} · {{check.result.elapsed_ms}} 毫秒</p><time class="text-xs text-white/40">{{formatTime(check.result.checked_at)}}</time></article><p class="text-xs text-white/40">历史检查反映执行时的状态，不代表持续在线。</p></template>
      <p v-if="!loading&&!error&&!(tab==='tasks'?tasks.length:tab==='schedules'?schedules.length:history.length)" class="glass-card p-8 text-center text-sm text-white/45">暂无{{tab==='tasks'?'任务':tab==='schedules'?'定时计划':'检查历史'}}</p>
    </div>
    <div v-if="tab!=='schedules'" class="flex flex-wrap items-center justify-between gap-2 text-xs text-white/50"><span>共 {{total}} 条</span><div class="flex gap-2 items-center"><button class="ghost-button min-h-11" :disabled="page<=1||loading||busy" @click="page--;load()">上一页</button><span>第 {{page}} 页</span><button class="ghost-button min-h-11" :disabled="page*20>=total||loading||busy" @click="page++;load()">下一页</button></div></div>
  </div>
</template>
<script setup lang="ts">
import {computed,onMounted,onScopeDispose,ref} from 'vue'
import {useRoute} from 'vue-router'
import {automationApi,type SourceTask,type SourceSchedule,type CheckHistory,type JobConnection,type TaskStatus} from '../../api/automation'
import {activeTask,retryableTask,taskStatusLabels} from '../../utils/automation'
import {reportCommandKeys} from '../report/reportCommands'
import {useUserStore} from '../../stores/user'
const route=useRoute(),user=useUserStore(),tabs=[{key:'tasks',label:'任务记录'},{key:'schedules',label:'定时计划'},{key:'history',label:'检查历史'}]
const tab=ref('tasks'),connections=ref<JobConnection[]>([]),connectionID=ref(Number(route.query.connection_id)||undefined),kind=ref<'check'|'collect'>(route.query.kind==='collect'?'collect':'check'),intervalMinutes=ref(60),editingVersion=ref(0),tasks=ref<SourceTask[]>([]),schedules=ref<SourceSchedule[]>([]),history=ref<CheckHistory[]>([]),statusFilter=ref<TaskStatus|''>(''),page=ref(1),total=ref(0),loading=ref(false),busy=ref(false),error=ref(''),notice=ref('')
const selected=computed(()=>connections.value.find(c=>c.id===connectionID.value)),canCollect=computed(()=>['admin','developer'].includes(user.role)&&!!selected.value?.capabilities?.collect),controller=new AbortController(),keys=reportCommandKeys()
let alive=true,generation=0,timer:ReturnType<typeof setInterval>|undefined
const formatTime=(v:string)=>new Date(v).toLocaleString(),sourceName=(id:number)=>connections.value.find(c=>c.id===id)?.name||'个人连接已移除'
function resetPlan(){editingVersion.value=0}
function selectTab(value:string){tab.value=value;page.value=1;notice.value='';void load()}
async function load(){const run=++generation;loading.value=true;error.value='';try{if(tab.value==='tasks'){const r=await automationApi.tasks({status:statusFilter.value||undefined,page:page.value},controller.signal);if(alive&&run===generation){tasks.value=r.items;total.value=r.total}}else if(tab.value==='schedules'){const r=await automationApi.schedules(controller.signal);if(alive&&run===generation)schedules.value=r.items}else{const r=await automationApi.history({page:page.value},controller.signal);if(alive&&run===generation){history.value=r.items;total.value=r.total}}}catch(e){if(alive&&run===generation){tasks.value=[];schedules.value=[];history.value=[];error.value=e instanceof Error?e.message:'读取失败'}}finally{if(alive&&run===generation)loading.value=false}}
async function act(operation:()=>Promise<unknown>,message:string){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await operation();keys.clear();if(alive){notice.value=message;page.value=1;await load();window.dispatchEvent(new Event('dbhub-inbox-updated'))}}catch(e){if(alive)error.value=e instanceof Error?e.message:'提交失败，请刷新后核对'}finally{if(alive)busy.value=false}}
function createTask(){if(!connectionID.value)return;const body={connection_id:connectionID.value,kind:kind.value};void act(()=>automationApi.createTask({...body,request_id:keys.get('create',body)},controller.signal),'任务已加入队列')}
function cancelTask(task:SourceTask){void act(()=>automationApi.cancelTask(task.id,controller.signal),'取消请求已提交；已完成的操作不会撤回')}
function retryTask(task:SourceTask){void act(()=>automationApi.retryTask(task.id,keys.get('retry:'+task.id,{id:task.id}),controller.signal),'已创建新的重试任务')}
function editSchedule(s:SourceSchedule){connectionID.value=s.connection_id;kind.value=s.kind;intervalMinutes.value=s.interval_minutes;editingVersion.value=s.version;notice.value='修改后保存，将绑定当前配置';window.scrollTo({top:0})}
function saveSchedule(){if(!connectionID.value)return;const body={connection_id:connectionID.value,kind:kind.value,interval_minutes:intervalMinutes.value,enabled:true,version:editingVersion.value};void act(async()=>{await automationApi.saveSchedule(body,controller.signal);if(alive)editingVersion.value=0},'定时计划已启用')}
function pauseSchedule(s:SourceSchedule){void act(()=>automationApi.saveSchedule({connection_id:s.connection_id,kind:s.kind,interval_minutes:s.interval_minutes,enabled:false,version:s.version},controller.signal),'定时计划已暂停')}
onMounted(async()=>{try{const r=await automationApi.connections(controller.signal);if(!alive)return;connections.value=r.items;if(!connections.value.some(c=>c.id===connectionID.value))connectionID.value=connections.value[0]?.id;await load()}catch(e){if(alive)error.value=e instanceof Error?e.message:'读取个人连接失败'}if(alive)timer=setInterval(()=>{if(alive&&!loading.value&&!busy.value&&!document.hidden&&navigator.onLine&&tab.value==='tasks'&&tasks.value.some(t=>activeTask(t.status)))void load()},3000)})
onScopeDispose(()=>{alive=false;generation++;controller.abort();clearInterval(timer);keys.clear()})
</script>
